"""Create a portable report and figures from measured, decoded results."""
import csv,hashlib,html,json,pathlib,re,sys
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np

out=pathlib.Path(sys.argv[1]).resolve();runs=out/'runs'
cases=[json.loads(p.read_text()) for p in sorted(runs.glob('*/analysis.json')) if 'harnessValid' in json.loads(p.read_text())]
valid=[c for c in cases if c['harnessValid']]
final_names=['720p60-record','720p60-stream','1080p30-record','1080p30-stream','4k30-record','4k30-stream','controller-stall-1080p30','soak-1080p30-stream']
def fmt(v,places=2):return 'unavailable' if v is None else f'{v:.{places}f}'
rows=[]
for c in valid:
 r=c['resources'];a=c['audio']['activeWindow'];m=c['motion'];s=c['finalOutput'];sync=c['audio']['sync']
 rows.append({'case':c['case'],'resolution':f"{c['width']}×{c['height']} / {c['fps']} FPS",'mode':c['mode'],'activeSeconds':c['durationRequestedMs']/1000,'videoEncoderThreads':s.get('videoEncoderThreads',1),'qualityPassed':c['qualityPassed'],'cpuMeanCores':r['cpuMeanCores'],'cpuP95Cores':r['cpuP95Cores'],'rssPeakMiB':r['rssPeakMiB'],'pssPeakMiB':r['pssPeakMiB'],'rssSlopeMiBPerMinute':r['rssSlopeMiBPerMinuteAfterWarmup'],'pssSlopeMiBPerMinute':r['pssSlopeMiBPerMinuteAfterWarmup'],'distinctFps':m['distinctFps'],'maximumVisualHoldMs':m['maxHoldMs'],'maximumVideoPtsGapMs':m['maxPtsGapMs'],'audioQuietTotalMs':a['quietTotalMs'],'audioQuietMaximumMs':a['quietMaximumMs'],'audioMissingInputMs':s['missingAudioSamples']/48,'audioLateFrames':s['lateAudioSamples'],'audioOverflowDroppedFrames':s['droppedAudioSamples'],'maximumEncoderProgressLeadMs':s['maximumTrackLeadMs'],'maximumContentClockOffsetMs':sync['maximumAbsoluteMs'],'acceptedContentAnchors':sync['acceptedAnchors'],'queuedBytesAfterStop':s['queuedAudioBytes']+s['queuedVideoBytes']})
for row in rows:
 row['videoEncoderPreset']=next(c['finalOutput'].get('videoEncoderPreset','unavailable') for c in valid if c['case']==row['case'])
 row['trialGroup']='final' if row['case'] in final_names else 'diagnostic/history'
 row['ussPeakMiB']=next(c['resources'].get('ussPeakMiB') for c in valid if c['case']==row['case'])
 row['ussSlopeMiBPerMinute']=next(c['resources'].get('ussSlopeMiBPerMinuteAfterWarmup') for c in valid if c['case']==row['case'])
with (out/'summary.csv').open('w',newline='') as f:
 writer=csv.DictWriter(f,fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows)
(out/'summary.json').write_text(json.dumps({'cases':cases,'rows':rows},indent=2)+'\n')
final_rows=[next(r for r in rows if r['case']==name) for name in final_names if any(r['case']==name for r in rows)]
plt.rcParams.update({'figure.dpi':140,'font.size':9,'axes.spines.top':False,'axes.spines.right':False})
matrix=[r for r in final_rows if r['case'] in ['720p60-record','720p60-stream','1080p30-record','1080p30-stream','4k30-record','4k30-stream']]
if matrix:
 labels=[r['case'].replace('-', '\n') for r in matrix];x=np.arange(len(matrix));fig,axes=plt.subplots(5,1,figsize=(10,13),sharex=True)
 for ax,key,title,color in zip(axes,['cpuMeanCores','rssPeakMiB','distinctFps','maximumVisualHoldMs','audioQuietMaximumMs'],['Mean product CPU cores (4-core quota)','Peak summed RSS MiB (shared pages may be counted repeatedly)','Distinct marked video frames per active second','Longest visual marker hold (ms)','Longest decoded quiet interval in continuous audio (ms)'],['#247da7','#7971c6','#39836c','#ba7a28','#c35c51']):
  values=[r[key] for r in matrix];ax.bar(x,values,color=color);ax.set_title(title,loc='left');ax.grid(axis='y',alpha=.2)
  for i,v in enumerate(values):ax.text(i,v,f'{v:.2f}',ha='center',va='bottom',fontsize=8)
 axes[-1].set_xticks(x,labels);fig.tight_layout();fig.savefig(out/'resolution-results.png');plt.close(fig)
soak=next((c for c in valid if c['case']=='soak-1080p30-stream'),None)
if soak:
 series=json.loads((runs/soak['case']/'resource-series.json').read_text());fig,axes=plt.subplots(4,1,figsize=(10,10),sharex=True)
 axes[0].plot([r['atSeconds']/60 for r in series['series']],[r['cpuCores'] for r in series['series']],lw=.7);axes[0].set_ylabel('CPU cores')
 axes[1].plot([r['atSeconds']/60 for r in series['series']],[r['rssMiB'] for r in series['series']],label='Summed RSS')
 axes[1].plot([r['atSeconds']/60 for r in series['privateMemory']],[r['pssMiB'] for r in series['privateMemory']],label='PSS');axes[1].plot([r['atSeconds']/60 for r in series['privateMemory']],[r['ussMiB'] for r in series['privateMemory']],label='USS');axes[1].set_ylabel('MiB');axes[1].legend()
 for key in ['heapMiB','externalMiB','arrayBuffersMiB']:axes[2].plot([r['atSeconds']/60 for r in series['nodeMemory']],[r[key] for r in series['nodeMemory']],label=key)
 axes[2].set_ylabel('Node MiB');axes[2].legend()
 native=[json.loads(line) for line in (runs/soak['case']/'status.jsonl').read_text().splitlines()];t=[r['atMs']/60000 for r in native]
 axes[3].plot(t,[r['output']['queuedVideoBytes']/1024**2 for r in native],label='Retained video');axes[3].plot(t,[r['output']['queuedAudioBytes']/1024**2 for r in native],label='Retained audio');axes[3].set_ylabel('Queue MiB');axes[3].legend(loc='upper left')
 delay=axes[3].twinx();delay.plot(t,[r['output']['bufferedDelayMs'] for r in native],color='#a76c33',alpha=.6,label='Adaptive delay');delay.set_ylabel('Delay ms');delay.legend(loc='upper right');axes[3].set_xlabel('Active minutes');fig.suptitle('30-minute 1080p30 streaming memory profile (live unsanitized CEF)');fig.tight_layout();fig.savefig(out/'memory-profile.png');plt.close(fig)
fuzz_path=out/'fuzz/results.json';fuzz=json.loads(fuzz_path.read_text()) if fuzz_path.exists() else {'targets':[]}
for f in fuzz['targets']:
 log=(out/'logs'/('fuzz-'+f['name']+'.log')).read_text();f['stats']={k:int(v) for k,v in re.findall(r'stat::(\w+):\s+(\d+)',log)}
 done=re.findall(r'DONE\s+cov: (\d+) ft: (\d+)',log);f['finalCoverageCounters']={'coverage':int(done[-1][0]),'features':int(done[-1][1])} if done else None
(out/'fuzz/summary.json').write_text(json.dumps(fuzz,indent=2)+'\n')
host=json.loads((out/'tests/host-and-scope.json').read_text())
lines=['# SuiteCut native shared-clock implementation and verification','', 'Saved 11 October 2026 (Asia/Calcutta). All output media, logs, process samples, source/encoder PCM diagnostics, fuzz corpora and build evidence remain in this directory; JSON measurements retain UTC timestamps. Historical publication results were preserved.','', '## Result','', 'Native audio and video workers now hold at a common media boundary while CEF capture continues. This fixes the old 500 ms encoder lead allowance. Captured samples are retained during recoverable worker delays; absent source samples are counted and remain visible. This is not a claim that CEF capture continuity or perceptual lip sync is solved.','', '## Implementation','', '- Both tracks use one monotonic origin. A worker starts a block only after its partner completes through that block’s start. The maximum completed-position lead is one video/audio codec block, including codec-specific frame sizes.','- Requested CEF audio capture waits for its first PCM block, including silent PCM, before choosing the common epoch. Silent pages with no requested stream remain recordable. Stock CEF creates loopback capture after detecting audibility; it cannot announce a future page sound in advance. These continuous-audio benchmarks first start the AudioWorklet and wait for eight captured PCM callbacks; the per-run readiness metadata records that warmup. This is not a cold-first-sound guarantee.','- CEF now requests 1,024 frames at 48 kHz stereo, matching OBS Browser Source. The two 60-second pilots do not establish that block size alone causes a reliability improvement.','- The jitter buffer starts at 150 ms and adapts up to 960 ms. Capture queues remain bounded; late, missing and overflow-dropped frames are separate counters. Stop drains and releases retained ownership.','- Realtime video selects the nearest buffered capture within half a frame interval; distant future frames remain held. A decoded FFV1 regression verifies three jittered captures remain ordered/distinct at 60 FPS. Offline ordering is unchanged.','- H.264 uses one slice thread through 1080p, two above 1080p and three at 4K. 4K uses ultrafast instead of veryfast to leave capture headroom on this four-core quota. This changes compression efficiency; no matched perceptual-quality or GPU-encoder comparison is claimed.','- The persistent-audio candidate was rebased onto CEF revision 708dc14 and dry-applies with zero patch fuzz. It is not compiled or enabled in these binaries; this host has a 32 GiB filesystem with under 2 GiB free. It addresses silent/first-sound capture lifecycle, not recovery of interior lost Chromium samples.','- New status includes active-source missing frames, each worker’s coordination waits and maximum encoder-progress lead. The latter is not a lip-sync measurement.','', '## Verification','', '- Eight CTest cases pass in the normal build and again with Clang 19 AddressSanitizer/UndefinedBehaviorSanitizer and LeakSanitizer enabled. Includes 160 concurrent ownership/lifecycle cycles, codec checks, scaler-failure cleanup, silent/requested startup, timeouts, pause/resume and shutdown.','- A traced 60-second real-browser repeat blocks the Node controller for 2,000 ms: native capture receives 94 audio callbacks while encoders finish 60 video frames and 96,256 audio frames, with no missing input, PCM copy mismatch or decoded quiet interval. The untraced earlier case’s severe interruption preceded its intentional stall; its cause remains unisolated. See tests/controller-stall-observation.json.','- 24 focused SDK tests pass; TypeScript build passes. These are existing native adapters; full Chromium and external-browser memory safety are outside this run.','- Four injected 250 ms encoder stalls (audio/video × 30/60 FPS) preserve every decoded PCM sample in order, with zero missing/late/dropped frames and a one-block progress bound. Restoring only the old 500 ms allowance fails this regression; see logs/tests-negative-control.log.','']
for f in fuzz['targets']:lines.append(f"- {f['name']} libFuzzer: {f['wallSeconds']:.1f} seconds, {f['stats'].get('number_of_executed_units','unavailable')} executed units, exit {f['exitCode']}, artifacts {len(f['artifacts'])}, corpus {f['corpusFiles']} files, peak sanitizer-process RSS {f['stats'].get('peak_rss_mb','unavailable')} MiB. See logs/fuzz-{f['name']}.log.")
lines+=['','## Capture results','','Recording and loopback RTMP streaming run separately. Each resolution uses two active minutes; the controller-stall case uses one minute; the memory soak uses 30 minutes. Every decoded output is inspected for actual dimensions, marker/PTS progress, captured click/text/select/scroll states, continuous-audio quiet intervals and known sample-content correlation against the recorded AudioContext clock. The table shows final-code trials only. All earlier tuning/failed/interrupted trials remain in summary.csv and runs/*/analysis.json, with their original media and logs.','','| Case | Mean CPU cores | Peak RSS MiB | Distinct FPS | Max visual hold ms | Audio quiet total / max ms | Encoder lead ms | Quality checks |','|---|---:|---:|---:|---:|---:|---:|---|']
for r in final_rows:lines.append(f"| {r['case']} | {r['cpuMeanCores']:.2f} | {r['rssPeakMiB']:.1f} | {r['distinctFps']:.2f} | {r['maximumVisualHoldMs']:.1f} | {r['audioQuietTotalMs']} / {r['audioQuietMaximumMs']} | {r['maximumEncoderProgressLeadMs']:.2f} | {'Pass' if r['qualityPassed'] else 'Defects observed'} |")
lines+=['','Final encoder budgets: '+', '.join(f"{r['case']}: {r['videoEncoderThreads']} threads / {r['videoEncoderPreset']}" for r in final_rows), '', '![Resolution results](resolution-results.png)','','Earlier one-thread 4K trials failed to drain before the SDK stop timeout. Three slices alone with veryfast still accumulated substantial backlog. Ultrafast plus three slices is the final 4K configuration; the retained tuning trials show the performance/compression tradeoff.','', 'A separate set of trials encountered cgroup file-cache pressure despite modest live process RSS. Those trials are labeled cache-pressure and excluded from the final table. Only owned clean files were advised out of the page cache between trials; no file bytes were deleted or modified. The interruption and cleanup records remain under tests/. Final trials record cgroup memory events so this confound remains inspectable.','','## Remaining defects and attribution','']
for c in cases:
 if not c['harnessValid']:lines.append(f"- **Failed capture {c['case']}**: {c.get('error',c['workloadStatus'])}. Retained under runs/{c['case']}; not counted as a successful quality or performance trial.")
for c in valid:
 lines.append(f"- **{c['case']}**: {'; '.join(c['issues']) if c['issues'] else 'No listed delivery defects observed.'} Content-clock max absolute offset: {fmt(c['audio']['sync']['maximumAbsoluteMs'])} ms across {c['audio']['sync']['acceptedAnchors']} accepted anchors.")
 if c.get('trace'):
  t=c['trace'];lines.append(f"  Traced interior missing input: {fmt(t.get('interiorMissingMs'))} ms; eventually uncovered: {fmt(t.get('interiorEventuallyUncoveredMs'))} ms; source-copy mismatched frames: {t.get('interiorSourceCopyMismatchedFrames','unavailable')}; silent source packets across the full trace (including warmup/shutdown): {t['sourceSilentPackets']}; silent packets fully within the output window: {t.get('sourceSilentPacketsWithinOutput','unavailable')}; raw timestamp gaps: {len(t.get('rawSourceTimelineGaps',[]))}; normalizer-introduced gap events: {len(t.get('normalizerIntroducedGapEvents',[]))}. Full source timestamps and raw PCM are retained.")
lines+=['','The previous matched OBS/CEF audio report also observed quiet source PCM and output interruptions on this host (a 105 ms longest quiet interval in the 60-second tapped matched OBS recording). That historical trial used a different capture sequence and is not a direct performance comparison with this matrix.','', 'A zero copy-mismatch count establishes preservation of the available traced PCM, not that Chromium generated every required sample. CEF’s capture implementation discards Chromium glitch metadata. The retained pinned source shows audibility-triggered loopback creation; larger capture timestamp discontinuities and provided zero PCM survive container multiplexing. A container cannot recover those samples.','', 'Content-clock offsets use deterministic waveform correlation and the nearest encoded 10 ms AudioContext marker. They include browser scheduling/capture effects and marker quantization; they exclude display/network latency and are not a direct perceptual lip-sync certificate. Every correlation/anchor is retained.','']
if soak:
 r=soak['resources'];lines+=['## Sustained memory profile','',f"30-minute 1080p30 streaming: peak RSS {r['rssPeakMiB']:.1f} MiB, peak PSS {fmt(r['pssPeakMiB'])} MiB, peak USS {fmt(r.get('ussPeakMiB'))} MiB. Slopes after the first two minutes: RSS {fmt(r['rssSlopeMiBPerMinuteAfterWarmup'])} MiB/min, PSS {fmt(r['pssSlopeMiBPerMinuteAfterWarmup'])} MiB/min, USS {fmt(r.get('ussSlopeMiBPerMinuteAfterWarmup'))} MiB/min, Node heap {fmt(r['nodeHeapSlopeMiBPerMinuteAfterWarmup'])} MiB/min. Summed RSS double-counts some shared pages; PSS/USS are recorded every ten seconds. Peak retained queues: video {fmt(r.get('nativeQueuedVideoPeakMiB'))} MiB and audio {fmt(r.get('nativeQueuedAudioPeakMiB'))} MiB; adaptive delay changed from {fmt(r.get('nativeAdaptiveBufferInitialMs'))} to at most {fmt(r.get('nativeAdaptiveBufferMaximumMs'))} ms. The fourth chart shows that retained-buffer history alongside memory. Growth alone does not prove a leak, and a finite test cannot establish universal leak freedom.",'','![Memory profile](memory-profile.png)','']
lines+=['## Scope and reproduction','', 'Full fuzz campaigns use 600 seconds per target, a 512-byte input limit, five-second per-input timeout and 1 GiB RSS limit. Earlier short smoke and interrupted campaigns are retained separately and are not counted as the final campaigns.', '',host['budgetEnforcement'],'','Product CPU/RSS includes the SDK controller, native capture/encoder process and browser children. The loopback receiver, Xvfb and PulseAudio are excluded from product totals but retained in the raw resource inventory and included in the RSS guard. Samples are every 500 ms; no intentional capture/build/decoder/fuzzer overlap. Four-core affinity does not provide an isolated physical host.','',host['networkBoundary'],'','CEF and the dynamically linked FFmpeg libraries were not rebuilt with sanitizers. The campaigns instrument SuiteCut native code and inspect allocator leaks in the tested processes. They do not certify complete CEF/Chromium, FFmpeg, graphics-driver, browser-automation or GPU memory safety.','', 'Run from the repository root:','', '```sh','python benchmarks/native-sync/shared-clock-matrix.py /absolute/path/to/new-evidence-dir','SYNC_DIRECTORY=/absolute/path/to/new-evidence-dir/runs/soak-1080p30-stream SYNC_DURATION_MS=1800000 SYNC_MODE=stream SYNC_PROFILE=memory python benchmarks/native-sync/shared-clock-runtime.py','python benchmarks/native-sync/analyze-shared-clock.py /absolute/path/to/new-evidence-dir/runs/*','python benchmarks/native-sync/fuzz-shared-clock.py /absolute/path/to/new-evidence-dir 600','python benchmarks/native-sync/report-shared-clock.py /absolute/path/to/new-evidence-dir','```','', 'The fuzz campaign requires the retained Clang sanitizer build and initialized corpus directories. Build flags, binary/source hashes, runtime versions and host scope are saved under tests/ and logs/. Failed calibration captures remain under runs/pilot-1080p30 and runs/lifecycle-1080p30; they are diagnostics, not successful final matrix trials.','', 'OBS behavior was taken from the pinned review in ../../obs-cef/2026-10-10-audio-source-review and the existing matched captures in ../../obs-cef/2026-10-10-native-audio-profile. This run does not add a new OBS performance comparison or claim better capture quality than OBS.']
text='\n'.join(lines)+'\n';(out/'report.md').write_text(text)
try:
 import markdown
 body=markdown.markdown(text,extensions=['tables','fenced_code'])
except ImportError:
 columns=[('case','Case'),('cpuMeanCores','Mean CPU cores'),('rssPeakMiB','Peak RSS MiB'),('distinctFps','Distinct FPS'),('audioQuietMaximumMs','Longest quiet ms'),('maximumEncoderProgressLeadMs','Encoder lead ms')]
 table='<table><thead><tr>'+''.join('<th>'+label+'</th>' for key,label in columns)+'</tr></thead><tbody>'
 for row in final_rows:table+='<tr>'+''.join('<td>'+html.escape(row[key] if isinstance(row[key],str) else fmt(row[key]))+'</td>' for key,label in columns)+'</tr>'
 table+='</tbody></table>'
 images=''.join('<p><img alt="Measured benchmark figure" src="'+name+'"></p>' for name in ['resolution-results.png','memory-profile.png'] if (out/name).exists())
 body='<h1>SuiteCut shared-clock evidence</h1><p>Encoder coordination is fixed. Remaining source audio and video defects are retained in the results. Read the detailed evidence below for scope and limitations.</p>'+table+images+'<details open><summary>Full report and reproduction</summary><pre>'+html.escape(text)+'</pre></details>'
(out/'report.html').write_text('<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SuiteCut shared-clock evidence</title><style>body{font:16px/1.6 system-ui;max-width:1200px;margin:40px auto;padding:0 20px;color:#182c3c}table{border-collapse:collapse;font-size:13px;width:100%;display:block;overflow:auto}td,th{border:1px solid #ddd;padding:8px}img{max-width:100%}pre{background:#eef2f5;overflow:auto;padding:15px}a{color:#14729a}</style>'+body)
print(json.dumps({'decodedCases':len(valid),'qualityPassed':sum(c['qualityPassed'] for c in valid),'report':str(out/'report.html')}))
